const D = { energy:.55, scale:1, hue:200, speed:1, density:.5, x:.5, y:.8, pose:'dance', style:'degas', act:'recital', flare:.6, grace:.6, seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- helpers ----
const md = (a, n) => ((a % n) + n) % n;
const frc = v => v - Math.floor(v);
const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
const sn = (tt, off) => { const f = Math.floor(tt), xq = tt - f; return (fr(f + off) * (1 - xq) + fr(f + 1 + off) * xq - .5) * 2; };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;
S.lastBeat = K.beat;

const u = Math.min(width, height);
const sc = u * P.scale / 330;
const bt = K.beat * P.speed;
const sub = frc(bt);
const en = P.energy * (.5 + .5 * K.intensity);
const H = md(P.hue, 360);
const ink = P.style === 'inkwash', neon = P.style === 'neon', riso = P.style === 'riso';
const GR = .85 + P.grace * .35;   // limb length morph

// ---- caches ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.hatch = [];
  for (let i = 0; i < 30; i++) S.hatch.push({
    x: (fr(i * 3 + 2) - .5) * 340, y: -4 + fr(i * 3 + 3) * 16,
    a: -.5 + fr(i * 5 + 4) * 1, l: 10 + fr(i * 7 + 5) * 22, ph: fr(i * 9 + 6) * 6.2832
  });
  S.mote = [];
  for (let i = 0; i < 12; i++) S.mote.push({ x: (fr(i * 11 + 30) - .5) * 220, v: .35 + fr(i * 13 + 31) * .6, ph: fr(i * 17 + 32) * 6.2832 });
}
if (!S.spr) {
  S.spr = createGraphics(64, 64);
  S.spr.noStroke();
  for (let r = 30; r > 0; r--) { S.spr.fill(255, 6); S.spr.ellipse(32, 32, r * 2.1, r * 2.1); }
}

// ---- pose program ----
let pose = P.pose;
if (pose === 'dance') {
  const ph = md(bt, 32);
  if (P.act === 'rehearsal') {
    pose = ph < 12 ? 'plie' : ph < 20 ? 'arabesque' : ph < 26 ? (K.section % 3 === 2 ? 'pirouette' : 'idle') : 'idle';
  } else {
    pose = ph < 8 ? 'plie' : ph < 16 ? 'pirouette' : ph < 24 ? 'arabesque' : 'idle';
  }
}

const wob = sn(K.t * .7, 100);           // balance corrections
const breath = Math.sin(K.t * .27) * .5 + K.swell * .5;
let plie = 0, rise = 0, spinA = null, lean = 0, legBack = 0, sway = 0;
let aL1 = .35, aL2 = -.55, aR1 = -.35, aR2 = .55;   // ports de bras (bras bas default)
let headT = sn(K.t * .2, 44) * .08;
let flare = P.flare * (.55 + K.swell * .3 * en + A.rms * .8);

if (pose === 'plie') {
  const deep = Math.floor(md(bt, 4)) % 2 === 0 ? .5 : 1;
  plie = Math.sin(sub * Math.PI) * deep * (.4 + .6 * en);
  const op = .5 + plie * .9;
  aL1 = op; aL2 = -.7; aR1 = -op; aR2 = .7;
  headT = plie * .06;
  flare += plie * .12;
} else if (pose === 'pirouette') {
  spinA = bt * Math.PI * (P.act === 'rehearsal' ? .5 : 1);
  aL1 = 2.6; aL2 = -.7; aR1 = -2.6; aR2 = .7;   // high fifth
  rise = .8;
  flare += .22 + en * .1;
} else if (pose === 'arabesque') {
  rise = K.swell * .5 * en + .2;
  legBack = .5 + .18 * K.swell * en + wob * .06;
  lean = .22 + K.swell * .04;
  aR1 = -1.62; aR2 = .12;                        // front arm reaches
  aL1 = 1.15; aL2 = -.25;                        // back arm trails
  headT = -.1 + wob * .03;
} else { // idle rest / bourree
  sway = Math.sin(bt * Math.PI * .5) * 2.5 * en + sn(K.t * .31, 88) * 2;
  rise = K.pulse * .18 * en;
  aL1 = .35 + breath * .06; aR1 = -.35 - breath * .06;
}

const hipY = -78 + plie * 24 - rise * 5;
const facing = spinA == null ? 1 : Math.cos(spinA);
const fx = spinA == null ? 1 : Math.max(.24, Math.abs(facing));

// ---- style plumbing ----
let PASS = 1;
function FC(h, s, b, a) {
  if (PASS === 0) { noFill(); return; }
  if (PASS === 3) { fill(338, 62, 97, a * .8); return; }
  if (PASS === 4) { fill(224, 52, 93, a * .8); return; }
  if (neon) { fill(250, 42, 13, a); return; }
  if (ink) { fill(0, 0, 88, a * .3); return; }
  fill(h, s, b, a);
}
function SC(h, s, b, a, w) {
  if (PASS === 0) { stroke(H, 70, 100, 18); strokeWeight(w * 3.2); noFill(); return; }
  if (PASS === 3) { stroke(338, 62, 97, a * .8); }
  else if (PASS === 4) { stroke(224, 52, 93, a * .8); }
  else if (neon) { stroke(H, 70, 100, a); }
  else if (ink) { stroke(0, 0, 96, a); }
  else stroke(h, s, b, a);
  strokeWeight(w);
}
const detailPass = () => PASS === 1 || PASS === 4;

// ---- body parts (stroke-limb gesture rig) ----
function shoe() {
  noStroke(); FC(348, 45, 92, 95);
  beginShape(); vertex(-2.6, -1); vertex(2.6, -1); vertex(1, 8.5); vertex(-1, 8.5); endShape(CLOSE);
}
function legL(x, y, a1, a2, w) {
  push(); translate(x, y); rotate(a1);
  SC(21, 26, 92, 96, w * 1.12); line(0, 0, 0, 40 * GR);
  if (PASS === 1 && !ink && !neon) { SC(12, 55, 48, 40, w * .3); line(w * .42, 2, w * .42, 38 * GR); }
  SC(21, 26, 92, 96, w);
  translate(0, 40 * GR); rotate(a2);
  line(0, 0, 0, 36 * GR);
  translate(0, 36 * GR);
  shoe();
  pop();
}
function armL(x, y, a1, a2, w) {
  push(); translate(x, y); rotate(a1);
  SC(21, 26, 93, 96, w); line(0, 0, 0, 24 * GR);
  translate(0, 24 * GR); rotate(a2);
  line(0, 0, 0, 22 * GR);
  translate(0, 22 * GR);
  noStroke(); FC(21, 28, 94, 96); ellipse(0, 1.5, 5, 5.5);
  pop();
}
function tutu(x, y, fl2, aMul) {
  const tw = 62 * (1 + fl2 * .55), th = 15 * (1 + fl2 * .4);
  noStroke();
  for (let i = 3; i >= 1; i--) {
    FC(md(H + i * 8, 360), 24 - i * 4, 96, (20 - i * 4) * aMul);
    ellipse(x, y + i * 2.4, tw * (1 - i * .07), th * (1 + i * .16));
  }
  FC(H, 22, 97, 72 * aMul);
  ellipse(x, y, tw, th);
  for (let i = 0; i < 12; i++) {
    const aa = fr(i * 7 + 21) * 6.2832 + Math.sin(K.t * .4 + i) * .06;
    SC(md(H + 20, 360), 32, 99, 36 * aMul, 1.1);
    const rx = Math.cos(aa) * tw * .5, ry = Math.sin(aa) * th * .5;
    line(x + rx * .82, y + ry * .82, x + rx * 1.06, y + ry * 1.06);
  }
  noStroke();
}
function drawDancer() {
  push();
  translate(sway, 0);
  // legs (under tutu)
  if (pose === 'plie') {
    legL(-4, hipY, .5 + plie * .5, -(1.02 + plie * 1.0), 6);
    legL(4, hipY, -(.5 + plie * .5), 1.02 + plie * 1.0, 6);
  } else if (pose === 'pirouette') {
    push(); scale(fx, 1);
    legL(0, hipY, .02 + wob * .02, -.02, 6);
    if (Math.abs(facing) > .35) legL(1, hipY, -1.12, 2.25, 5.4);
    pop();
  } else if (pose === 'arabesque') {
    legL(-2, hipY, .05 + wob * .02, -.04, 6);
    legL(0, hipY, -(1.55 + legBack), -.22, 5.6);
  } else {
    legL(-3.5, hipY, .04 + wob * .015, -.03, 6);
    legL(3.5, hipY, -.04, .03, 6);
  }
  // tutu (unsquashed disc — reads as spinning plate)
  tutu(0, hipY - 5, flare, 1);
  if (spinA != null && P.flare > .05) {
    blendMode(ADD); noFill();
    for (let g = 1; g <= 3; g++) {
      SC(md(H + g * 12, 360), 40, 100, 22 - g * 6, 1.6);
      ellipse(0, hipY - 5, (62 * (1 + flare * .55)) * (1 + g * .09), (15 * (1 + flare * .4)) * (1 + g * .14));
    }
    blendMode(BLEND); noStroke();
  }
  // torso + head (squashed during pirouette)
  push();
  translate(0, hipY - 5);
  rotate(lean * (pose === 'arabesque' ? 1 : 0) + sway * .008);
  scale(fx, 1);
  const bs = 1 + breath * .025;
  noStroke(); FC(H, 30, 90, 100);
  push(); scale(bs, 1);
  beginShape();
  vertex(-7, 0); vertex(7, 0);
  bezierVertex(9, -12, 8.5, -20, 7.5, -27);
  vertex(-7.5, -27);
  bezierVertex(-8.5, -20, -9, -12, -7, 0);
  endShape(CLOSE);
  pop();
  if (detailPass() && !ink) { noStroke(); FC(md(H + 15, 360), 40, 80, 45); ellipse(0, -8, 8 * bs, 14); }
  armL(-8, -25, aL1, aL2, 4.4);
  armL(8, -25, aR1, aR2, 4.4);
  // neck + head
  SC(21, 26, 92, 96, 3); line(0, -27, 0, -33);
  push(); translate(0, -33); rotate(headT);
  noStroke(); FC(22, 28, 94, 100);
  ellipse(0, -7, 15.5, 17);
  const back = spinA != null && facing < 0;
  FC(24, 62, 26, 100);
  if (back) { ellipse(0, -9, 15, 15); ellipse(0, -16.5, 7.5, 7); }
  else {
    arc(0, -11, 16.5, 12, Math.PI - .3, 6.2832 + .3, CHORD);
    ellipse(0, -16.5, 7.5, 7);
    if (detailPass()) {
      const blink = frc(K.t * .11 + fr(9) * 3) < .05;
      fill(0, 0, 20, 95);
      if (blink) { rect(-4.5, -8, 3, .9, 1); rect(1.5, -8, 3, .9, 1); }
      else { ellipse(-3, -7.5, 1.9, 2.3); ellipse(3, -7.5, 1.9, 2.3); }
      fill(355, 55, 80, 70); ellipse(0, -2.6, 2.6, 1.5);
      fill(350, 45, 95, 30); ellipse(-4.6, -4.4, 3, 2); ellipse(4.6, -4.4, 3, 2);
    }
  }
  pop();
  pop();
  pop();
}

// ---- render ----
push();
translate(P.x * width + Math.sin(K.t * .16) * 10 * sc, P.y * height);
scale(sc);

// warm stage glow (drifts side to side across sections)
const gx = Math.sin(K.t * .045 + K.section * .8) * 55;
blendMode(ADD);
tint(neon ? H : 38, neon ? 55 : 40, 95, clp(6 + K.intensity * 9 + A.bass * 8, 0, 24));
image(S.spr, gx - 150, -300, 300, 300);
noTint();
blendMode(BLEND);

// rehearsal-room floor: line + pastel hatch scuffs
SC(30, 20, ink ? 70 : 55, 30, 1.2);
line(-190, 6, 190, 6);
const nh = Math.floor(P.density * 28);
for (let i = 0; i < nh; i++) {
  const hch = S.hatch[i];
  const shim = 10 + (Math.sin(K.t * .5 + hch.ph) * .5 + .5) * 8;
  SC(28, 25, 75, shim, 1);
  push(); translate(hch.x, hch.y); rotate(hch.a * .3);
  line(-hch.l / 2, 0, hch.l / 2, 0);
  pop();
}
noStroke();

// soft shadow under dancer
fill(0, 0, 0, 35);
ellipse(sway, 3, 56 + flare * 20, 10);

// figure — style passes
if (neon) {
  PASS = 0; blendMode(ADD); drawDancer(); blendMode(BLEND);
  PASS = 1; drawDancer();
} else if (riso) {
  PASS = 3; push(); translate(-2 - fr(1) * 1.5, -1.4); drawDancer(); pop();
  PASS = 4; push(); translate(2 + fr(2) * 1.5, 1.4); drawDancer(); pop();
  PASS = 1;
} else {
  PASS = 1; drawDancer();
}

// ink style: red seal stamp
if (ink) {
  noStroke(); fill(5, 80, 72, 85);
  rect(120, -36, 16, 16, 2);
  fill(0, 0, 95, 80);
  rect(124, -32, 3, 3); rect(129, -32, 3, 8); rect(124, -27, 3, 3);
}

// dust motes in the light (treble sparkle on top of baseline drift)
const spark = clp(A.treble * 1.4 + .25, 0, 1);
blendMode(ADD); noStroke();
for (let i = 0; i < 12; i++) {
  const mo = S.mote[i];
  const my2 = -20 - frc(K.t * .03 * mo.v + mo.ph) * 240;
  const mx2 = mo.x + gx * .3 + sn(K.t * .2, i * 31) * 12;
  const al = (Math.sin(K.t * (1.5 + mo.v) + mo.ph) * .5 + .5) * 40 * spark;
  fill(45, 15, 100, clp(al, 0, 45));
  ellipse(mx2, my2, 2.2, 2.2);
}
blendMode(BLEND);
pop();
